-- 087_biweekly_commercial_review.sql
-- Roadmap F.32: durable 14-day Commercial / Variation Review cycles.

CREATE TABLE IF NOT EXISTS public.project_commercial_review_cycles(
 id uuid PRIMARY KEY,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,review_number integer NOT NULL CHECK(review_number>0),
 period_start date NOT NULL,period_end date NOT NULL,status text NOT NULL CHECK(status IN('OPEN','CLOSED')),
 opening_pending_exposure numeric(24,2)NOT NULL CHECK(opening_pending_exposure>=0),closing_pending_exposure numeric(24,2)CHECK(closing_pending_exposure>=0),
 opening_approved_variations numeric(24,2)NOT NULL CHECK(opening_approved_variations>=0),closing_approved_variations numeric(24,2)CHECK(closing_approved_variations>=0),
 opened_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,opened_at timestamptz NOT NULL DEFAULT now(),
 closed_by uuid REFERENCES auth.users(id)ON DELETE RESTRICT,closed_at timestamptz,closing_note text NOT NULL DEFAULT''CHECK(char_length(closing_note)<=3000),
 UNIQUE(project_id,review_number),CHECK(period_end=period_start+13),CHECK((status='OPEN'AND closed_at IS NULL AND closed_by IS NULL)OR(status='CLOSED'AND closed_at IS NOT NULL AND closed_by IS NOT NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS project_commercial_review_one_open_idx ON public.project_commercial_review_cycles(project_id)WHERE status='OPEN';
CREATE TABLE IF NOT EXISTS public.project_commercial_review_items(
 review_cycle_id uuid NOT NULL REFERENCES public.project_commercial_review_cycles(id)ON DELETE RESTRICT,variation_id uuid NOT NULL,project_id bigint NOT NULL,
 variation_number integer NOT NULL,title text NOT NULL,work_group_id uuid NOT NULL,status_at_open text NOT NULL,bucket_at_open text NOT NULL CHECK(bucket_at_open IN('NEW','PENDING','APPROVED','REJECTED','DISPUTED')),
 proposed_amount numeric(24,2)NOT NULL,approved_amount_at_open numeric(24,2),status_at_close text,bucket_at_close text CHECK(bucket_at_close IN('NEW','PENDING','APPROVED','REJECTED','DISPUTED')),
 approved_amount_at_close numeric(24,2),PRIMARY KEY(review_cycle_id,variation_id),FOREIGN KEY(variation_id,project_id)REFERENCES public.project_variations(id,project_id)ON DELETE RESTRICT
);
ALTER TABLE public.project_commercial_review_cycles ENABLE ROW LEVEL SECURITY;ALTER TABLE public.project_commercial_review_items ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS project_commercial_reviews_select ON public.project_commercial_review_cycles;CREATE POLICY project_commercial_reviews_select ON public.project_commercial_review_cycles FOR SELECT TO authenticated USING(lower((SELECT role FROM public.profiles WHERE id=auth.uid()))IN('pm','admin')AND public.can_write_project(project_id));
DROP POLICY IF EXISTS project_commercial_review_items_select ON public.project_commercial_review_items;CREATE POLICY project_commercial_review_items_select ON public.project_commercial_review_items FOR SELECT TO authenticated USING(lower((SELECT role FROM public.profiles WHERE id=auth.uid()))IN('pm','admin')AND public.can_write_project(project_id));
REVOKE ALL ON TABLE public.project_commercial_review_cycles,public.project_commercial_review_items FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_commercial_review_cycles,public.project_commercial_review_items TO authenticated;

CREATE OR REPLACE FUNCTION private.variation_review_bucket(p_status text)RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT CASE p_status WHEN'SUBMITTED'THEN'NEW'WHEN'UNDER_REVIEW'THEN'PENDING'WHEN'APPROVED'THEN'APPROVED'WHEN'REJECTED'THEN'REJECTED'WHEN'REVISION_REQUIRED'THEN'DISPUTED'ELSE'PENDING'END$$;

CREATE OR REPLACE FUNCTION public.get_project_commercial_review(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE v_uid uuid:=auth.uid();v_open public.project_commercial_review_cycles%ROWTYPE;v_last public.project_commercial_review_cycles%ROWTYPE;v_due date;
BEGIN IF v_uid IS NULL OR lower((SELECT role FROM public.profiles WHERE id=v_uid))NOT IN('pm','admin')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'COMMERCIAL_REVIEW_FORBIDDEN'USING ERRCODE='42501';END IF;
 SELECT *INTO v_open FROM public.project_commercial_review_cycles WHERE project_id=p_project_id AND status='OPEN';SELECT *INTO v_last FROM public.project_commercial_review_cycles WHERE project_id=p_project_id ORDER BY review_number DESC LIMIT 1;v_due:=CASE WHEN v_last.id IS NULL THEN current_date ELSE v_last.period_end+14 END;
 RETURN jsonb_build_object('cadenceDays',14,'reviewDue',v_open.id IS NULL AND current_date>=v_due,'nextReviewDue',v_due,'openCycle',CASE WHEN v_open.id IS NULL THEN NULL ELSE jsonb_build_object('reviewCycleId',v_open.id,'reviewNumber',v_open.review_number,'periodStart',v_open.period_start,'periodEnd',v_open.period_end,'openedAt',v_open.opened_at,'openingPendingExposure',v_open.opening_pending_exposure,'openingApprovedVariations',v_open.opening_approved_variations,'items',COALESCE((SELECT jsonb_agg(jsonb_build_object('variationId',i.variation_id,'variationNumber',i.variation_number,'title',i.title,'bucket',i.bucket_at_open,'status',i.status_at_open,'proposedAmount',i.proposed_amount,'approvedAmount',i.approved_amount_at_open)ORDER BY i.bucket_at_open,i.variation_number)FROM public.project_commercial_review_items i WHERE i.review_cycle_id=v_open.id),'[]'::jsonb))END,'history',COALESCE((SELECT jsonb_agg(jsonb_build_object('reviewCycleId',c.id,'reviewNumber',c.review_number,'periodStart',c.period_start,'periodEnd',c.period_end,'status',c.status,'openingPendingExposure',c.opening_pending_exposure,'closingPendingExposure',c.closing_pending_exposure,'openingApprovedVariations',c.opening_approved_variations,'closingApprovedVariations',c.closing_approved_variations,'closingNote',c.closing_note,'closedAt',c.closed_at)ORDER BY c.review_number DESC)FROM public.project_commercial_review_cycles c WHERE c.project_id=p_project_id),'[]'::jsonb));
END;$$;

CREATE OR REPLACE FUNCTION public.open_project_commercial_review(p_project_id bigint,p_cycle_id uuid,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,private AS $$
DECLARE v_uid uuid:=auth.uid();v_request public.write_command_requests%ROWTYPE;v_number integer;v_start date;v_pending numeric;v_approved numeric;v_result jsonb;
BEGIN IF v_uid IS NULL OR lower((SELECT role FROM public.profiles WHERE id=v_uid))NOT IN('pm','admin')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'COMMERCIAL_REVIEW_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_cycle_id IS NULL OR p_client_request_id IS NULL THEN RAISE EXCEPTION'INVALID_COMMERCIAL_REVIEW_COMMAND'USING ERRCODE='22023';END IF;
 INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(v_uid,'commercial_review.open',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO v_request FROM public.write_command_requests WHERE actor_id=v_uid AND operation='commercial_review.open'AND client_request_id=p_client_request_id;IF v_request.response IS NOT NULL THEN RETURN v_request.response||jsonb_build_object('idempotentReplay',true);END IF;
 PERFORM pg_advisory_xact_lock(p_project_id);IF EXISTS(SELECT 1 FROM public.project_commercial_review_cycles WHERE project_id=p_project_id AND status='OPEN')THEN RAISE EXCEPTION'COMMERCIAL_REVIEW_ALREADY_OPEN'USING ERRCODE='55000';END IF;SELECT COALESCE(max(review_number),0)+1 INTO v_number FROM public.project_commercial_review_cycles WHERE project_id=p_project_id;v_start:=current_date-13;
 SELECT COALESCE(sum(proposed_amount)FILTER(WHERE status IN('SUBMITTED','UNDER_REVIEW','REVISION_REQUIRED')),0),COALESCE(sum(approved_amount)FILTER(WHERE status='APPROVED'),0)INTO v_pending,v_approved FROM public.project_variations WHERE project_id=p_project_id;
 INSERT INTO public.project_commercial_review_cycles(id,project_id,review_number,period_start,period_end,status,opening_pending_exposure,opening_approved_variations,opened_by)VALUES(p_cycle_id,p_project_id,v_number,v_start,v_start+13,'OPEN',v_pending,v_approved,v_uid);
 INSERT INTO public.project_commercial_review_items(review_cycle_id,variation_id,project_id,variation_number,title,work_group_id,status_at_open,bucket_at_open,proposed_amount,approved_amount_at_open)SELECT p_cycle_id,v.id,v.project_id,v.variation_number,v.title,v.work_group_id,v.status,private.variation_review_bucket(v.status),v.proposed_amount,v.approved_amount FROM public.project_variations v WHERE v.project_id=p_project_id AND v.status<>'DRAFT';
 v_result:=jsonb_build_object('reviewCycleId',p_cycle_id,'reviewNumber',v_number,'periodStart',v_start,'periodEnd',v_start+13,'itemCount',(SELECT count(*)FROM public.project_commercial_review_items WHERE review_cycle_id=p_cycle_id),'pendingExposure',v_pending,'approvedVariations',v_approved);UPDATE public.write_command_requests SET response=v_result,completed_at=now()WHERE id=v_request.id;RETURN v_result||jsonb_build_object('idempotentReplay',false);
END;$$;

CREATE OR REPLACE FUNCTION public.close_project_commercial_review(p_cycle_id uuid,p_closing_note text,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,private AS $$
DECLARE v_uid uuid:=auth.uid();v_cycle public.project_commercial_review_cycles%ROWTYPE;v_request public.write_command_requests%ROWTYPE;v_pending numeric;v_approved numeric;v_result jsonb;
BEGIN SELECT *INTO v_cycle FROM public.project_commercial_review_cycles WHERE id=p_cycle_id FOR UPDATE;IF v_cycle.id IS NULL THEN RAISE EXCEPTION'COMMERCIAL_REVIEW_NOT_FOUND'USING ERRCODE='P0002';END IF;IF v_uid IS NULL OR lower((SELECT role FROM public.profiles WHERE id=v_uid))NOT IN('pm','admin')OR public.can_write_project(v_cycle.project_id)IS NOT TRUE THEN RAISE EXCEPTION'COMMERCIAL_REVIEW_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_client_request_id IS NULL OR btrim(COALESCE(p_closing_note,''))=''OR char_length(p_closing_note)>3000 THEN RAISE EXCEPTION'INVALID_COMMERCIAL_REVIEW_COMMAND'USING ERRCODE='22023';END IF;
 INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(v_uid,'commercial_review.close',p_client_request_id,v_cycle.project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO v_request FROM public.write_command_requests WHERE actor_id=v_uid AND operation='commercial_review.close'AND client_request_id=p_client_request_id;IF v_request.response IS NOT NULL THEN RETURN v_request.response||jsonb_build_object('idempotentReplay',true);END IF;IF v_cycle.status<>'OPEN'THEN RAISE EXCEPTION'COMMERCIAL_REVIEW_NOT_OPEN'USING ERRCODE='55000';END IF;
 SELECT COALESCE(sum(proposed_amount)FILTER(WHERE status IN('SUBMITTED','UNDER_REVIEW','REVISION_REQUIRED')),0),COALESCE(sum(approved_amount)FILTER(WHERE status='APPROVED'),0)INTO v_pending,v_approved FROM public.project_variations WHERE project_id=v_cycle.project_id;
 UPDATE public.project_commercial_review_items i SET status_at_close=v.status,bucket_at_close=private.variation_review_bucket(v.status),approved_amount_at_close=v.approved_amount FROM public.project_variations v WHERE i.review_cycle_id=p_cycle_id AND v.id=i.variation_id;
 UPDATE public.project_commercial_review_cycles SET status='CLOSED',closing_pending_exposure=v_pending,closing_approved_variations=v_approved,closing_note=btrim(p_closing_note),closed_by=v_uid,closed_at=now()WHERE id=p_cycle_id;
 v_result:=jsonb_build_object('reviewCycleId',p_cycle_id,'status','CLOSED','closingPendingExposure',v_pending,'closingApprovedVariations',v_approved);UPDATE public.write_command_requests SET response=v_result,completed_at=now()WHERE id=v_request.id;RETURN v_result||jsonb_build_object('idempotentReplay',false);
END;$$;

REVOKE ALL ON FUNCTION private.variation_review_bucket(text)FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.get_project_commercial_review(bigint),public.open_project_commercial_review(bigint,uuid,uuid),public.close_project_commercial_review(uuid,text,uuid)FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_project_commercial_review(bigint),public.open_project_commercial_review(bigint,uuid,uuid),public.close_project_commercial_review(uuid,text,uuid)TO authenticated;
